(2864590, 401023, 60698, '<td valign="top">Beginning to think that there was no hope for a beautiful image in this challenge.... finally one perfect, beautiful abstract Macro.</td>', 'Beginning to think that there was no hope for a beautiful image in this challenge.... finally one perfect, beautiful abstract Macro.', '2006-09-25 22:03:19.000000', NULL, 1),
(2864592, 400184, 3102, '<td valign="top">Very, very nice!  I like the sharpness here.  I''m not usually a fan of toning like this, but it works really well here.</td>', 'Very, very nice!  I like the sharpness here.  I''m not usually a fan of toning like this, but it works really well here.', '2006-09-25 22:03:54.000000', NULL, 1),
(2864595, 398009, 3102, '<td valign="top">I can''t even pinpoint *why* I like this so much, but it''s one of my favorites in the challenge.  I like the colors... that must be it :)</td>', 'I can''t even pinpoint *why* I like this so much, but it''s one of my favorites in the challenge.  I like the colors... that must be it :)', '2006-09-25 22:04:28.000000', NULL, 1),
