(2876987, 400694, 50695, '<td valign="top">A good fulfillment of the challenge, but it''s your title that bumps this to an 8.</td>', 'A good fulfillment of the challenge, but it''s your title that bumps this to an 8.', '2006-09-29 23:39:16.000000', NULL, 1),
(2876989, 398894, 50695, '<td valign="top">I have a rule that anyone who can make me laugh out loud (utter derision doesn''t count) automatically gets at least a 7. I do hope in your description that you let us know how many times you have mounted Modnoc, though... 8</td>', 'I have a rule that anyone who can make me laugh out loud (utter derision doesn''t count) automatically gets at least a 7. I do hope in your description that you let us know how many times you have mounted Modnoc, though... 8', '2006-09-29 23:39:38.000000', NULL, 1),
