(2877437, 400719, 61191, '<td valign="top">Grand Piano''s strings? Great shot! Like your use of DOF, lighting is excellent.</td>', 'Grand Piano''s strings? Great shot! Like your use of DOF, lighting is excellent.', '2006-09-30 06:39:32.000000', NULL, 1),
(2877439, 400565, 61191, '<td valign="top">Like your idea and object but your shot is very noisy. Try to shoot at lower ISO.</td>', 'Like your idea and object but your shot is very noisy. Try to shoot at lower ISO.', '2006-09-30 06:40:55.000000', NULL, 1),
(2877440, 399831, 61191, '<td valign="top">Great composition and lighting. I don''t like the soft focus here. When you take a shot of the structure of a leaf it has to be quite sharp imho. Try to sharpen your shot via postprocessing.</td>', 'Great composition and lighting. I don''t like the soft focus here. When you take a shot of the structure of a leaf it has to be quite sharp imho. Try to sharpen your shot via postprocessing.', '2006-09-30 06:43:39.000000', NULL, 1),
(2877441, 397696, 61191, '<td valign="top">Great idea, the title fits in well!</td>', 'Great idea, the title fits in well!', '2006-09-30 06:44:57.000000', NULL, 1),
(2877443, 401080, 61191, '<td valign="top">You make me think about your title: I see no green in here. Did you choose it because green being the complement color of magenta? Anyway: nice shot, a bit too blurry.</td>', 'You make me think about your title: I see no green in here. Did you choose it because green being the complement color of magenta? Anyway: nice shot, a bit too blurry.', '2006-09-30 06:46:33.000000', NULL, 1),
(2877444, 401111, 61191, '<td valign="top">Interesting object. Submit a larger shot next time.</td>', 'Interesting object. Submit a larger shot next time.', '2006-09-30 06:47:36.000000', NULL, 1),
(2877449, 398221, 61191, '<td valign="top">Those horseshoe crabs are quite interesting animals. Sad to see it dead... I just wish your shot was "more macro". This is not very abstract because you instantly know what the image shows. Anyway: great find, well done!</td>', 'Those horseshoe crabs are quite interesting animals. Sad to see it dead... I just wish your shot was "more macro". This is not very abstract because you instantly know what the image shows. Anyway: great find, well done!', '2006-09-30 06:54:36.000000', NULL, 1),
(2877451, 400941, 61191, '<td valign="top">I really like your composition and lighting but I think the green pops too much. I would prefer a more subtle green.</td>', 'I really like your composition and lighting but I think the green pops too much. I would prefer a more subtle green.', '2006-09-30 06:56:35.000000', NULL, 1),
(2877453, 400154, 61191, '<td valign="top">Nice colors but too blurry.</td>', 'Nice colors but too blurry.', '2006-09-30 06:57:38.000000', NULL, 1),
