(2877761, 398824, 40484, '<td valign="top">excellent macro but not very abstract, IMO</td>', 'excellent macro but not very abstract, IMO', '2006-09-30 12:02:26.000000', NULL, 1),
(2877775, 400441, 56048, '<td valign="top">very well done. i am not sure what i''m looking at, but i know i like it. interested to see what details accompany this photo and how it was done, particularly how it bleeds to white.</td>', 'very well done. i am not sure what i''m looking at, but i know i like it. interested to see what details accompany this photo and how it was done, particularly how it bleeds to white.', '2006-09-30 12:09:06.000000', NULL, 1),
