INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2877782, 400675, 56048, '<td valign="top">love the colors in this one. nice soft effect.</td>', 'love the colors in this one. nice soft effect.', '2006-09-30 12:11:27.000000', NULL, 1),
(2877788, 400615, 56048, '<td valign="top">nice shot.</td>', 'nice shot.', '2006-09-30 12:12:43.000000', NULL, 1),
(2877817, 400962, 58452, '<td valign="top">The texture is exquisite.  Wonderful.  As is my habit, I went through the images again on the last day and re-rated a few.  Bumped this one up to 10.  I hope you ribbon.</td>', 'The texture is exquisite.  Wonderful.  As is my habit, I went through the images again on the last day and re-rated a few.  Bumped this one up to 10.  I hope you ribbon.', '2006-09-30 12:39:28.000000', NULL, 1),
(2877819, 399768, 58452, '<td valign="top">Somehow your image reminds me of the boiling insides of a violent thunderstorm.  I love your abstraction.</td>', 'Somehow your image reminds me of the boiling insides of a violent thunderstorm.  I love your abstraction.', '2006-09-30 12:41:06.000000', NULL, 1),
(2877821, 400675, 58452, '<td valign="top">Soothing colors and shapes.</td>', 'Soothing colors and shapes.', '2006-09-30 12:41:54.000000', NULL, 1),
(2877822, 399479, 58452, '<td valign="top">I love the color contrasts and the perfect smoothness of the forms.</td>', 'I love the color contrasts and the perfect smoothness of the forms.', '2006-09-30 12:42:30.000000', NULL, 1),
(2877826, 401020, 58452, '<td valign="top">I love green and I love the natural color contrast around the oval with the catchlight.  Beautiful texture across the entire image.</td>', 'I love green and I love the natural color contrast around the oval with the catchlight.  Beautiful texture across the entire image.', '2006-09-30 12:43:59.000000', NULL, 1),
(2877829, 399470, 58452, '<td valign="top">As google would say, did you mean Radiance?<br/>heehhehe  That aside I love the color and texture and composition of your image.  Give me a warm and fuzzy feeling!</td>', 'As google would say, did you mean Radiance?heehhehe  That aside I love the color and texture and composition of your image.  Give me a warm and fuzzy feeling!', '2006-09-30 12:45:53.000000', NULL, 1),
(2877830, 400761, 58452, '<td valign="top">This is one of those images whose forms, textures, and patterns call out to me.  I don''t know why, but maybe it''s because I like green!</td>', 'This is one of those images whose forms, textures, and patterns call out to me.  I don''t know why, but maybe it''s because I like green!', '2006-09-30 12:47:04.000000', NULL, 1),
(2877834, 400973, 58452, '<td valign="top">Truly a "holy" composition.  ;)  Nice image.</td>', 'Truly a "holy" composition.  ;)  Nice image.', '2006-09-30 12:48:58.000000', NULL, 1),
(2877836, 399733, 58452, '<td valign="top">Nice color contrast and I love the glow of the leaf veins.</td>', 'Nice color contrast and I love the glow of the leaf veins.', '2006-09-30 12:49:29.000000', NULL, 1),
(2877838, 398756, 58452, '<td valign="top">Second look on this one and bumping it a point to 9.  It does indeed look like beautiful flames.</td>', 'Second look on this one and bumping it a point to 9.  It does indeed look like beautiful flames.', '2006-09-30 12:50:36.000000', NULL, 1),
(2877840, 401041, 58452, '<td valign="top">You''re gonna wish you''d entered a version of this in Pastels!  Absolutely beautiful textures and colors.</td>', 'You''re gonna wish you''d entered a version of this in Pastels!  Absolutely beautiful textures and colors.', '2006-09-30 12:51:53.000000', NULL, 1),
(2877842, 399228, 58452, '<td valign="top">Truly glorious.  ;)</td>', 'Truly glorious.  ;)', '2006-09-30 12:53:29.000000', NULL, 1),
(2877844, 400969, 58452, '<td valign="top">Love the colors.</td>', 'Love the colors.', '2006-09-30 12:53:45.000000', NULL, 1),
(2877849, 400602, 58452, '<td valign="top">Hey!  My keyboard isn''t arraigned like that.  hehehe  Nice lines.</td>', 'Hey!  My keyboard isn''t arraigned like that.  hehehe  Nice lines.', '2006-09-30 12:56:28.000000', NULL, 1),
(2877855, 397812, 55838, '<td valign="top">Very pretty and dramatic.  Beautiful curves, light, and color.  Perfectly cropped.  A touch of something messy at the bottom but that doesn''t take away much.  I like your choice of border.  Back to bump to 8.</td>', 'Very pretty and dramatic.  Beautiful curves, light, and color.  Perfectly cropped.  A touch of something messy at the bottom but that doesn''t take away much.  I like your choice of border.  Back to bump to 8.', '2006-09-30 13:03:21.000000', NULL, 1),
(2877857, 400675, 55838, '<td valign="top">Lovely color tones and I like the sharpness on the little bubble.  Beautifully done.  Back to bump to 8.</td>', 'Lovely color tones and I like the sharpness on the little bubble.  Beautifully done.  Back to bump to 8.', '2006-09-30 13:04:53.000000', NULL, 1),
(2877864, 400770, 55838, '<td valign="top">This is cool.  Beautiful understated color tones.  Very attractive composition.  Back to bump to 8.</td>', 'This is cool.  Beautiful understated color tones.  Very attractive composition.  Back to bump to 8.', '2006-09-30 13:07:45.000000', NULL, 1),
(2877865, 400835, 55838, '<td valign="top">Ah - how fun!  Interesting composition and nice coloring &amp; focus.  Bumping to 8.</td>', 'Ah - how fun!  Interesting composition and nice coloring & focus.  Bumping to 8.', '2006-09-30 13:08:41.000000', NULL, 1),
(2877870, 399228, 55838, '<td valign="top">Georgeous color and nice composition.  Well cropped and nicely bordered.  Bumping to 8.</td>', 'Georgeous color and nice composition.  Well cropped and nicely bordered.  Bumping to 8.', '2006-09-30 13:10:04.000000', NULL, 1),
(2877872, 400891, 55838, '<td valign="top">Beautiful long dramatic lines and perfect coloring.  Lovely composition and I like your choice of border.  Back to bump to 8.<br/>*********************<br/>Back again.  Ok ok - you talked me into it....9.  One of my top picks.  Nice job!</td>', 'Beautiful long dramatic lines and perfect coloring.  Lovely composition and I like your choice of border.  Back to bump to 8.*********************Back again.  Ok ok - you talked me into it....9.  One of my top picks.  Nice job!', '2006-09-30 13:13:41.000000', NULL, 1),
(2877877, 400915, 55838, '<td valign="top">So very clean and I like the tones &amp; light.  Back to bump up to 8 - hey it kind of looks like an "8" - was that subliminal messaging to the voters? :)<br/>**********************<br/>Back again.  Just kidding...I think it''s a 9 - here''s another bump.  One of my top picks.</td>', 'So very clean and I like the tones & light.  Back to bump up to 8 - hey it kind of looks like an "8" - was that subliminal messaging to the voters? :)**********************Back again.  Just kidding...I think it''s a 9 - here''s another bump.  One of my top picks.', '2006-09-30 13:15:27.000000', NULL, 1),
(2878092, 401073, 44611, '<td valign="top">Good tones and detail.</td>', 'Good tones and detail.', '2006-09-30 15:05:40.000000', NULL, 1),
(2878096, 398221, 44611, '<td valign="top">This is so unusual and the colours are lovely and vibrant.  I think the seaweed may be a bit distracting and can''t help wondering how this would have looked without it.  A well seen and captured image for this challenge.</td>', 'This is so unusual and the colours are lovely and vibrant.  I think the seaweed may be a bit distracting and can''t help wondering how this would have looked without it.  A well seen and captured image for this challenge.', '2006-09-30 15:07:00.000000', NULL, 1),
(2878098, 400128, 44611, '<td valign="top">An incredible shot - the water seems truly alive.  Great colours and the slow shutter speed adds a real air of mystery.</td>', 'An incredible shot - the water seems truly alive.  Great colours and the slow shutter speed adds a real air of mystery.', '2006-09-30 15:07:43.000000', NULL, 1),
(2878099, 400793, 44611, '<td valign="top">I love the colour, lighting and simplicity of this, but the horizontal presentation bugs me for some reason.</td>', 'I love the colour, lighting and simplicity of this, but the horizontal presentation bugs me for some reason.', '2006-09-30 15:09:22.000000', NULL, 1),
(2878100, 401023, 44611, '<td valign="top">Brilliantly abstract - I love the blues.</td>', 'Brilliantly abstract - I love the blues.', '2006-09-30 15:09:33.000000', NULL, 1),
(2878122, 400296, 31533, '<td valign="top">Nice abstract composition but not smooth enough for my taste. I can see too many small flaws on my monitor. Good one nevertheless. Good luck.</td>', 'Nice abstract composition but not smooth enough for my taste. I can see too many small flaws on my monitor. Good one nevertheless. Good luck.', '2006-09-30 15:30:25.000000', NULL, 1),
