(2885572, 399768, 60862, '<td valign="top">Beautiful shot.  You amaze me - all that creativity in the self-portrait series and then you go and win a ribbon to boot.  Congrats!</td>', 'Beautiful shot.  You amaze me - all that creativity in the self-portrait series and then you go and win a ribbon to boot.  Congrats!', '2006-10-02 01:41:06.000000', NULL, 0),
